package ru.projectkingdom.administration;
import java.util.*;import net.minecraft.core.*;import net.minecraft.server.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import ru.projectkingdom.npc.*;
public class WarehouseRoomHarness{
 static final BlockPos FIRST=new BlockPos(0,60,0),SECOND=new BlockPos(1,60,1);
 record Fixture(MinecraftServer server,ServerPlayer player,UUID town,KingdomCentralWarehouseRooms rooms){}
 static Fixture fixture(){var server=new MinecraftServer();var id=UUID.randomUUID();var town=UUID.randomUUID();var player=new ServerPlayer(server,id);KingdomCivicsData.get(server).town=new KingdomCivicsData.Town(town,id);player.containerMenu=new AdministrativeCoreMenu(town,new BlockPos(-2,60,0));var rooms=KingdomCentralWarehouseRooms.get(server);server.world.containers.put(new BlockPos(0,61,0),new Container(){});check(rooms.begin(player,KingdomCentralWarehouseRooms.Kind.GENERAL),"begin rejected");equal(KingdomCentralWarehouseRooms.Result.FIRST_CORNER,rooms.select(player,FIRST));return new Fixture(server,player,town,rooms);}
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}static void equal(Object expected,Object got){if(!Objects.equals(expected,got))throw new AssertionError("expected "+expected+", got "+got);}
 public static void main(String[]args){switch(args[0]){
 case "floor"->{var f=fixture();equal(KingdomCentralWarehouseRooms.Result.CREATED,f.rooms.select(f.player,SECOND));var r=f.rooms.rooms(f.town).get(0);equal(new BlockPos(0,60,0),r.min());equal(new BlockPos(1,62,1),r.max());equal(12,r.volume());check(!f.rooms.hasSession(f.player.getUUID()),"successful survey retained");}
 case "diagonal"->{var f=fixture();equal(KingdomCentralWarehouseRooms.Result.CREATED,f.rooms.select(f.player,new BlockPos(1,62,1)));equal(12,f.rooms.rooms(f.town).get(0).volume());}
 case "retry"->{var f=fixture();equal(KingdomCentralWarehouseRooms.Result.TOO_LARGE,f.rooms.select(f.player,FIRST));check(f.rooms.hasSession(f.player.getUUID()),"invalid second corner lost first point");equal(KingdomCentralWarehouseRooms.Result.CREATED,f.rooms.select(f.player,SECOND));equal(1,f.rooms.rooms(f.town).size());}
 case "height"->{var f=fixture();equal(KingdomCentralWarehouseRooms.Result.CREATED,f.rooms.select(f.player,new BlockPos(1,61,1)));equal(3,f.rooms.rooms(f.town).get(0).max().getY()-f.rooms.rooms(f.town).get(0).min().getY()+1);}
 case "no_storage"->{var f=fixture();f.server.world.containers.clear();equal(KingdomCentralWarehouseRooms.Result.CREATED,f.rooms.select(f.player,SECOND));equal(1,f.rooms.rooms(f.town).size());var room=f.rooms.rooms(f.town).get(0);check(f.rooms.inspect(f.server.world,room).loaded(),"empty mapped room must be loaded");equal(0,f.rooms.inspect(f.server.world,room).containers());f.server.world.containers.put(new BlockPos(0,61,0),new Container(){});equal(1,f.rooms.inspect(f.server.world,room).containers());}
 case "rights"->{var f=fixture();KingdomCivicsData.get(f.server).town=new KingdomCivicsData.Town(f.town,UUID.randomUUID());equal(KingdomCentralWarehouseRooms.Result.NO_RIGHTS,f.rooms.select(f.player,SECOND));check(!f.rooms.hasSession(f.player.getUUID()),"revoked survey retained");equal(0,f.rooms.rooms(f.town).size());}
 case "dimension"->{var f=fixture();f.server.world.dimension="minecraft:the_nether";equal(KingdomCentralWarehouseRooms.Result.WRONG_DIMENSION,f.rooms.select(f.player,SECOND));check(!f.rooms.hasSession(f.player.getUUID()),"cross-dimension survey retained");}
 case "core_inside"->{var f=fixture();equal(KingdomCentralWarehouseRooms.Result.CREATED,f.rooms.select(f.player,new BlockPos(-2,60,1)));check(f.rooms.rooms(f.town).get(0).contains(new BlockPos(-2,60,0)),"central warehouse core can be inside its own room");}
 case "retry_far"->{var f=fixture();f.player.pos=new BlockPos(30,60,0);equal(KingdomCentralWarehouseRooms.Result.TOO_FAR,f.rooms.select(f.player,SECOND));check(f.rooms.hasSession(f.player.getUUID()),"far click incorrectly discarded first");f.player.pos=new BlockPos(0,60,0);equal(KingdomCentralWarehouseRooms.Result.CREATED,f.rooms.select(f.player,SECOND));}
 case "upper_limit"->{var f=fixture();f.player.pos=new BlockPos(17,62,1);equal(KingdomCentralWarehouseRooms.Result.TOO_LARGE,f.rooms.select(f.player,new BlockPos(17,62,1)));check(f.rooms.hasSession(f.player.getUUID()),"oversize survey lost first point");f.player.pos=new BlockPos(0,60,0);equal(KingdomCentralWarehouseRooms.Result.CREATED,f.rooms.select(f.player,SECOND));}
 default->throw new IllegalArgumentException(args[0]);}System.out.println("PASS warehouse selection: "+args[0]);}
}
